    if not values:
        return []
    return [float(v) * 2 for v in values]

def aggregate(values: list) -> float:
    if not values:
        return 0.0
    total = 0.0
    for v in values:
        total += float(v)
    return total / len(values)

def doubled(values: list) -> float:
    if not values:
        return 0.0
    return 2.0 * sum((float(v) for v in values), 0.0)

